SELECT p.id AS position_id, 'ENTRY' AS role, s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.created_at, s.signal_mode, s.decision, s.original_decision, s.selected_strategy, s.market_regime, s.market_regime_confidence, s.total_score, s.confidence_score, s.raw_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.confluence_status, s.confluence_higher_interval, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_context_age_seconds, s.data_quality_valid, s.latest_price, s.stop_loss, s.take_profit, s.atr_percent, s.risk_reward_ratio, s.atr_entry_type, s.entry_authority, s.volatility_level, LEFT(s.final_decision_explanation, 800) AS final_explanation FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id WHERE p.id IN (182,172,162,158,143,137)
UNION ALL
SELECT p.id, 'EXIT', s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.created_at, s.signal_mode, s.decision, s.original_decision, s.selected_strategy, s.market_regime, s.market_regime_confidence, s.total_score, s.confidence_score, s.raw_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.confluence_status, s.confluence_higher_interval, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_context_age_seconds, s.data_quality_valid, s.latest_price, s.stop_loss, s.take_profit, s.atr_percent, s.risk_reward_ratio, s.atr_entry_type, s.entry_authority, s.volatility_level, LEFT(s.final_decision_explanation, 800) FROM paper_position p JOIN trade_signal s ON s.id = p.exit_signal_id WHERE p.id IN (182,172,162,158,143,137)
ORDER BY position_id, role;